//! Reconcile the lexical scopes produced by the resolver with TypeScript's
//! declaration merging. Private bindings stay local to a body; exported values
//! are visible from every body, including bodies preceding their declaration.
use rustc_hash::{FxHashMap, FxHashSet};
use swc_atoms::Atom;
use swc_common::{Mark, SyntaxContext};
use swc_ecma_ast::*;
use swc_ecma_utils::{find_pat_ids, ExprFactory, QueryRef, RefRewriter};
use swc_ecma_visit::{noop_visit_type, Visit, VisitMut, VisitMutWith, VisitWith};

pub(crate) fn reconcile(program: &mut Program, unresolved_mark: Mark) {
    let mut declarations = Declarations::default();
    program.visit_with(&mut declarations);
    program.visit_mut_with(&mut Canonicalize(&declarations.aliases));
    // Collect again after canonicalizing nested exported declarations. This
    // makes N.M in separate bodies denote the same merged declaration.
    let mut declarations = Declarations::default();
    program.visit_with(&mut declarations);
    program.visit_mut_with(&mut References {
        declarations: &declarations,
        frames: Vec::new(),
        unresolved: SyntaxContext::empty().apply_mark(unresolved_mark),
    });
}

#[derive(Default)]
struct Declarations {
    members: FxHashMap<Id, FxHashSet<Atom>>,
    exports: FxHashMap<(Id, Atom), Id>,
    aliases: FxHashMap<Id, Id>,
    namespace: Option<Id>,
}

impl Declarations {
    fn export(&mut self, id: Id) {
        let Some(namespace) = &self.namespace else { return };
        self.members.entry(namespace.clone()).or_default().insert(id.0.clone());
        let canonical = self.exports.entry((namespace.clone(), id.0.clone())).or_insert_with(|| id.clone());
        self.aliases.insert(id, canonical.clone());
    }

    fn body(&mut self, id: Id, body: &TsNamespaceBody) {
        let id = self.aliases.get(&id).cloned().unwrap_or(id);
        let old = self.namespace.replace(id);
        body.visit_with(self);
        self.namespace = old;
    }
}

impl Visit for Declarations {
    noop_visit_type!();

    fn visit_export_decl(&mut self, n: &ExportDecl) {
        match &n.decl {
            Decl::Var(n) if !n.declare => {
                for id in find_pat_ids::<_, Id>(&n.decls) { self.export(id); }
            }
            Decl::Fn(n) if !n.declare => self.export(n.ident.to_id()),
            Decl::Class(n) if !n.declare => self.export(n.ident.to_id()),
            Decl::TsEnum(n) => self.export(n.id.to_id()),
            Decl::TsModule(n) => {
                if let TsModuleName::Ident(id) = &n.id { self.export(id.to_id()); }
            }
            _ => {}
        }
        n.visit_children_with(self);
    }

    fn visit_ts_import_equals_decl(&mut self, n: &TsImportEqualsDecl) {
        if n.is_export && !n.is_type_only { self.export(n.id.to_id()); }
    }

    fn visit_ts_module_decl(&mut self, n: &TsModuleDecl) {
        if let (TsModuleName::Ident(id), Some(body)) = (&n.id, &n.body) {
            self.body(id.to_id(), body);
        }
    }

    fn visit_ts_namespace_decl(&mut self, n: &TsNamespaceDecl) {
        self.export(n.id.to_id());
        self.body(n.id.to_id(), &n.body);
    }

    fn visit_ts_enum_decl(&mut self, n: &TsEnumDecl) {
        let id = self.aliases.get(&n.id.to_id()).cloned().unwrap_or_else(|| n.id.to_id());
        let members = self.members.entry(id).or_default();
        for member in &n.members {
            match &member.id {
                TsEnumMemberId::Ident(id) => { members.insert(id.sym.clone()); }
                TsEnumMemberId::Str(s) => {
                    if let Some(name) = s.value.as_atom() { members.insert(name.clone()); }
                }
                #[cfg(swc_ast_unknown)]
                _ => {}
            }
        }
    }
}

struct Canonicalize<'a>(&'a FxHashMap<Id, Id>);
impl VisitMut for Canonicalize<'_> {
    fn visit_mut_ident(&mut self, n: &mut Ident) {
        if let Some(id) = self.0.get(&n.to_id()) { n.ctxt = id.1; }
    }
}

/// Resolved ids distinguish a body's bindings (including nested parameters and
/// block bindings) from outer bindings with the same spelling.
#[derive(Default)]
struct Locals(FxHashSet<Id>);
impl Visit for Locals {
    noop_visit_type!();
    fn visit_binding_ident(&mut self, n: &BindingIdent) { self.0.insert(n.to_id()); }
    fn visit_fn_decl(&mut self, n: &FnDecl) {
        self.0.insert(n.ident.to_id());
        n.function.visit_with(self);
    }
    fn visit_class_decl(&mut self, n: &ClassDecl) {
        self.0.insert(n.ident.to_id());
        n.class.visit_with(self);
    }
    fn visit_fn_expr(&mut self, n: &FnExpr) {
        if let Some(id) = &n.ident { self.0.insert(id.to_id()); }
        n.function.visit_with(self);
    }
    fn visit_class_expr(&mut self, n: &ClassExpr) {
        if let Some(id) = &n.ident { self.0.insert(id.to_id()); }
        n.class.visit_with(self);
    }
    fn visit_ts_module_decl(&mut self, n: &TsModuleDecl) {
        if let TsModuleName::Ident(id) = &n.id { self.0.insert(id.to_id()); }
        n.visit_children_with(self);
    }
    fn visit_ts_namespace_decl(&mut self, n: &TsNamespaceDecl) {
        self.0.insert(n.id.to_id());
        n.visit_children_with(self);
    }
    fn visit_ts_enum_decl(&mut self, n: &TsEnumDecl) {
        self.0.insert(n.id.to_id());
        n.members.visit_with(self);
    }
    fn visit_ts_import_equals_decl(&mut self, n: &TsImportEqualsDecl) { self.0.insert(n.id.to_id()); }
}

struct Frame { id: Id, locals: FxHashSet<Id>, is_enum: bool }
struct References<'a> {
    declarations: &'a Declarations,
    frames: Vec<Frame>,
    unresolved: SyntaxContext,
}
impl QueryRef for References<'_> {
    fn query_ref(&self, ident: &Ident) -> Option<Box<Expr>> {
        for frame in self.frames.iter().rev() {
            if frame.locals.contains(&ident.to_id()) { return None; }
            if self.declarations.members.get(&frame.id).is_some_and(|members| members.contains(&ident.sym)) {
                if frame.is_enum {
                    let mut ident = ident.clone();
                    ident.ctxt = self.unresolved;
                    return Some(ident.into());
                }
                return Some(frame.id.clone().make_member(ident.clone().into()).into());
            }
        }
        None
    }
    fn query_lhs(&self, ident: &Ident) -> Option<Box<Expr>> { self.query_ref(ident) }
    fn query_jsx(&self, ident: &Ident) -> Option<JSXElementName> {
        let Expr::Member(member) = *self.query_ref(ident)? else { return None };
        let Expr::Ident(obj) = *member.obj else { return None };
        Some(JSXMemberExpr { span: ident.span, obj: JSXObject::Ident(obj), prop: ident.clone().into() }.into())
    }
}
impl References<'_> {
    fn body(&mut self, id: Id, body: &mut TsNamespaceBody) {
        let mut locals = Locals::default();
        body.visit_with(&mut locals);
        self.frames.push(Frame { id, locals: locals.0, is_enum: false });
        body.visit_mut_with(self);
        self.frames.pop();
    }
}
impl VisitMut for References<'_> {
    fn visit_mut_ts_type(&mut self, _: &mut TsType) {}
    fn visit_mut_ts_module_decl(&mut self, n: &mut TsModuleDecl) {
        if let (TsModuleName::Ident(id), Some(body)) = (&n.id, &mut n.body) { self.body(id.to_id(), body); }
    }
    fn visit_mut_ts_namespace_decl(&mut self, n: &mut TsNamespaceDecl) { self.body(n.id.to_id(), &mut n.body); }
    fn visit_mut_ts_enum_decl(&mut self, n: &mut TsEnumDecl) {
        let mut locals = Locals::default();
        n.members.visit_with(&mut locals);
        self.frames.push(Frame { id: n.id.to_id(), locals: locals.0, is_enum: true });
        n.members.visit_mut_with(self);
        self.frames.pop();
    }
    fn visit_mut_expr(&mut self, n: &mut Expr) {
        n.visit_mut_children_with(self);
        RefRewriter { query: &*self }.exit_expr(n);
    }
    fn visit_mut_prop(&mut self, n: &mut Prop) {
        n.visit_mut_children_with(self);
        RefRewriter { query: &*self }.exit_prop(n);
    }
    fn visit_mut_simple_assign_target(&mut self, n: &mut SimpleAssignTarget) {
        n.visit_mut_children_with(self);
        RefRewriter { query: &*self }.exit_simple_assign_target(n);
    }
    fn visit_mut_jsx_element_name(&mut self, n: &mut JSXElementName) {
        n.visit_mut_children_with(self);
        RefRewriter { query: &*self }.exit_jsx_element_name(n);
    }
    fn visit_mut_jsx_object(&mut self, n: &mut JSXObject) {
        n.visit_mut_children_with(self);
        RefRewriter { query: &*self }.exit_jsx_object(n);
    }
}
