trait EnumInitItem: From<Stmt> {
    fn enum_decl_key(&self) -> Option<(Id, Span)>;
}
impl EnumInitItem for Stmt {
    fn enum_decl_key(&self) -> Option<(Id, Span)> {
        let Stmt::Decl(Decl::Var(decl)) = self else {
            return None;
        };
        decl.decls
            .first()?
            .name
            .as_ident()
            .map(|ident| ident.to_id())
    }
}
impl EnumInitItem for ModuleItem {
    fn enum_decl_key(&self) -> Option<(Id, Span)> {
